'<source type="image/webp" srcset="' + b + 'w400.webp 400w, ' + b + 'w800.webp 800w" sizes="(min-width: 52.5em) 34rem, 92vw">' +
'<img src="' + b + 'w800.jpg" width="800" height="800" alt="" decoding="async">';
p.querySelector('img').alt = alt || '';
